import React, { useState } from "react";
import { User, Mail, Lock } from "lucide-react";
import "./style.css"; // Ton fichier CSS personnalisé

const InputField = ({
  icon: Icon,
  type = "text",
  placeholder,
  value,
  onChange,
  error,
  id,
}) => (
  <div className="mb-3 position-relative">
    <div className="input-icon">
      <Icon size={20} />
    </div>
    <input
      type={type}
      className={`form-control custom-input ${error ? "is-invalid" : ""}`}
      placeholder={placeholder}
      value={value}
      onChange={onChange}
      id={id}
      style={{ paddingLeft: "3rem", height: "3.5rem" }}
    />
    {error && <div className="invalid-feedback">{error}</div>}
  </div>
);

export default function InscriptionBootstrap() {
  const [formData, setFormData] = useState({
    nomRepresentant: "",
    prenomRepresentant: "",
    email: "",
    password: "",
    password2: "",
  });

  const [errors, setErrors] = useState({});
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (field) => (e) => {
    setFormData((prev) => ({ ...prev, [field]: e.target.value }));
    if (errors[field]) {
      setErrors((prev) => ({ ...prev, [field]: "" }));
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.nomRepresentant.trim())
      newErrors.nomRepresentant = "Le nom du représentant est requis";
    if (!formData.prenomRepresentant.trim())
      newErrors.prenomRepresentant = "Le prénom du représentant est requis";

    if (!formData.email.trim()) {
      newErrors.email = "L'email est requis";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "Format d'email invalide";
    }

    if (!formData.password) {
      newErrors.password = "Le mot de passe est requis";
    }

    if (!formData.password2) {
      newErrors.password2 = "La confirmation du mot de passe est requise";
    } else if (formData.password !== formData.password2) {
      newErrors.password2 = "Les mots de passe ne correspondent pas";
    }

    return newErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const newErrors = validateForm();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    setIsLoading(true);
    try {
      const response = await fetch("http://localhost:8000/api/auth/register/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: formData.email,
          first_name: formData.prenomRepresentant,
          last_name: formData.nomRepresentant,
          password: formData.password,
          password2: formData.password2,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        const apiErrors = {};
        for (const key in data) {
          apiErrors[key] = Array.isArray(data[key]) ? data[key][0] : data[key];
        }
        setErrors(apiErrors);
      } else {
        alert("Inscription réussie !");
        window.location.href = "/connexion"; // Décommente si tu veux rediriger
      }
    } catch (error) {
      alert("Erreur réseau ou serveur");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      <link
        href="https://cdnjs.cloudflare.com/ajax/libs/bootstrap/5.3.0/css/bootstrap.min.css"
        rel="stylesheet"
      />
      {/* <div className="text-start acceuil-back-link">
        <a href="/" className="small text-decoration-none">
          ← Accueil
        </a>
      </div> */}

      <div className="d-flex align-items-center justify-content-center p-4 custom-bg">
        <div className="container">
          <div className="row justify-content-center">
            <div className="col-12 col-md-11 col-lg-10 col-xl-9">
              <div className="custom-card p-4 p-sm-5">
                <div className="text-center mb-4">
                  <h2 className="h2 fw-bold text-primary-custom mb-2">
                    Inscription Entreprise
                  </h2>
                  <p className="text-primary-custom opacity-75">
                    Rejoignez notre plateforme dès aujourd'hui
                  </p>
                </div>

                <form onSubmit={handleSubmit}>
                  <div className="row">
                    <div className="col-12 col-sm-6">
                      <InputField
                        icon={User}
                        placeholder="Nom du représentant"
                        value={formData.nomRepresentant}
                        onChange={handleChange("nomRepresentant")}
                        error={errors.nomRepresentant}
                        id="nomRepresentant"
                      />
                    </div>
                    <div className="col-12 col-sm-6">
                      <InputField
                        icon={User}
                        placeholder="Prénom du représentant"
                        value={formData.prenomRepresentant}
                        onChange={handleChange("prenomRepresentant")}
                        error={errors.prenomRepresentant}
                        id="prenomRepresentant"
                      />
                    </div>
                  </div>

                  <InputField
                    icon={Mail}
                    type="email"
                    placeholder="Adresse email"
                    value={formData.email}
                    onChange={handleChange("email")}
                    error={errors.email}
                    id="email"
                  />

                  <InputField
                    icon={Lock}
                    type="password"
                    placeholder="Mot de passe"
                    value={formData.password}
                    onChange={handleChange("password")}
                    error={errors.password}
                    id="password"
                  />

                  <InputField
                    icon={Lock}
                    type="password"
                    placeholder="Confirmer le mot de passe"
                    value={formData.password2}
                    onChange={handleChange("password2")}
                    error={errors.password2}
                    id="password2"
                  />

                  <div className="pt-3">
                    <button
                      type="submit"
                      className="custom-btn text-white w-100"
                      disabled={isLoading}
                    >
                      {isLoading
                        ? "Inscription en cours..."
                        : "Créer le compte entreprise"}
                    </button>
                  </div>
                </form>
                {/* Séparateur */}
                <div className="connexion-divider mb-4">
                  <span>Ou continuer avec</span>
                </div>

                <div className="row g-2 mb-4">
                  <div className=" col-3">
                    <button
                      type="button"
                      className="btn connexion-btn-social w-100"
                    >
                      <svg
                        width="16"
                        height="16"
                        viewBox="0 0 24 24"
                        fill="none"
                        xmlns="http://www.w3.org/2000/svg"
                        className="me-2"
                      >
                        <path
                          d="M22.56 12.25C22.56 11.47 22.49 10.72 22.36 10H12V14.26H17.92C17.66 15.63 16.9 16.79 15.77 17.57V20.34H19.32C21.41 18.42 22.56 15.6 22.56 12.25Z"
                          fill="#4285F4"
                        />
                        <path
                          d="M12 23C15.24 23 17.95 21.92 19.32 20.34L15.77 17.57C14.77 18.22 13.48 18.63 12 18.63C8.87 18.63 6.22 16.68 5.32 13.95H1.64V16.83C3.01 19.55 7.27 23 12 23Z"
                          fill="#34A853"
                        />
                        <path
                          d="M5.32 13.95C5.1 13.3 4.98 12.61 4.98 11.89C4.98 11.17 5.1 10.48 5.32 9.83V6.95H1.64C0.89 8.44 0.5 10.13 0.5 11.89C0.5 13.65 0.89 15.34 1.64 16.83L5.32 13.95Z"
                          fill="#FBBC05"
                        />
                        <path
                          d="M12 5.38C13.62 5.38 15.06 5.94 16.21 7.02L19.36 3.87C17.95 2.54 15.24 1.5 12 1.5C7.27 1.5 3.01 4.95 1.64 7.67L5.32 10.55C6.22 7.82 8.87 5.38 12 5.38Z"
                          fill="#EA4335"
                        />
                      </svg>
                      Google
                    </button>
                  </div>
                </div>

                <div className="text-center mt-4">
                  <p className="small text-primary-custom">
                    Déjà un compte ?{" "}
                    <a
                      href="/connexion"
                      className="text-orange-custom text-decoration-none fw-medium"
                    >
                      Se connecter
                    </a>
                  </p>
                </div>

                <div className="text-center mt-3">
                  <p className="small text-primary-custom opacity-75">
                    En vous inscrivant, vous acceptez nos{" "}
                    <a
                      href="#"
                      className="text-orange-custom text-decoration-none"
                    >
                      conditions d'utilisation
                    </a>{" "}
                    et notre{" "}
                    <a
                      href="#"
